WITH openivm_net AS (
  SELECT id,
    SUM(openivm_multiplicity) AS _net
  FROM memory.main.openivm_delta___openivm_mv_6d656d6f7279_6d61696e_6f70656e69766d5f72756e74696d655f70726f6265_ WHERE openivm_timestamp > CAST('2026-11-20 06:28:20.63175' AS TIMESTAMP)
  GROUP BY id
  HAVING SUM(openivm_multiplicity) != 0
)
, openivm_delete_net AS (
  SELECT * FROM openivm_net WHERE _net < 0
), openivm_delete_candidates AS (
  SELECT v.rowid, v.id AS id, d._net
  FROM memory.main.openivm_data___openivm_mv_6d656d6f7279_6d61696e_6f70656e69766d5f72756e74696d655f70726f6265_ v JOIN openivm_delete_net d ON v.id <=> d.id
), openivm_ranked_deletes AS (
  SELECT rowid, _net,
    ROW_NUMBER() OVER (PARTITION BY id ORDER BY rowid) AS _rn
  FROM openivm_delete_candidates
)
DELETE FROM memory.main.openivm_data___openivm_mv_6d656d6f7279_6d61696e_6f70656e69766d5f72756e74696d655f70726f6265_ WHERE rowid IN (
  SELECT rowid FROM openivm_ranked_deletes WHERE _rn <= -_net
);
